head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.skw = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 발행회사 목록 초기 조회를 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.onpageload();
 */
scwin.onpageload = function() {
    try {

        scwin.select_list_call();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_jongmok_oncelldblclick
 * @description 목록 행 더블클릭 — 선택 행의 회사코드·회사명을 "회사코드^회사명" 형태로 반환하고 팝업을 닫는다.
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 열 인덱스
 * @param {String} columnId 더블클릭한 열 ID
 * @returns {void}
 * @hidden N
 * @example scwin.grd_jongmok_oncelldblclick(0, 0, "comAbbrv");
 */
scwin.grd_jongmok_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        console.log(rowIndex+"|"+ columnIndex+"|"+ columnId);

        const pJongCode = dlt_select_list_content.getCellData(rowIndex, "isurCd");
        const pJongNm   = dlt_select_list_content.getCellData(rowIndex, "comAbbrv");
        const rtn = pJongCode +"^"+ pJongNm;

        $c.win.closePopup(rtn);

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.grd_jongmok_oncelldblclick" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description [조회] 버튼 클릭 — 입력 조건(회사명·시장·상장구분)으로 회사 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_search_onclick(e);
 */
scwin.img_search_onclick = function(e) {
    try {

        scwin.JongmokSearch();

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.img_search_onclick" });
    }
};

/**
 * @method
 * @name txb_jongmokName_onkeydown
 * @description 회사명 입력란 키다운 — Enter(13) 입력 시 회사 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_jongmokName_onkeydown(e);
 */
scwin.txb_jongmokName_onkeydown = function(e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.JongmokSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.txb_jongmokName_onkeydown" });
    }
};

