///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_select_list_submitdone
 * @description 발행회사 목록 조회 서브미션 완료 콜백 — 성공 시 목록을 그리드 데이터리스트에 반영하고, 실패 시 결과 메시지를 알린다.
 * @param {Object} e 서브미션 완료 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_select_list_submitdone(e);
 */
scwin.sbm_select_list_submitdone = function (e) {
    try {
        const result = e.responseJSON;

        if(result.success) {
            const obj = result.body;

            dlt_select_list_content.setJSON(obj.content);
        }
        else{
            $c.win.alert(result.message);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00007.sbm_select_list_submitdone" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name select_list_call
 * @description 초기 조회 — 기본 조건(전체)으로 발행회사 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.select_list_call();
 */
scwin.select_list_call = function() {

    dma_select_list.set("listStatCd", "A");
    dma_select_list.set("spotIsuTrdMktTpCd", "0");
    dma_select_list.set("searchComAbbrv", "");
    dma_select_list.set("beginIndex", "");
    dma_select_list.set("page",  1);
    dma_select_list.set("size",  10);

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
};

/**
 * @method
 * @name Jongmok
 * @description 가나다라..검색 — 초성/문자 범위를 조회 코드(A~M·AZ·ETC)로 변환하여 현재 조건과 함께 회사 목록을 조회한다.
 * @param {String} prevval 시작 초성/문자
 * @param {String} nextval 끝 경계 초성/문자
 * @returns {void}
 * @hidden N
 * @example scwin.Jongmok('가', '나');
 */
scwin.Jongmok = function(prevval, nextval) {
    let chgVal = "A";

    if ((prevval === "가") && (nextval === "나")) {
        chgVal = "A";

    } else if ((prevval === "나") && (nextval === "다")) {
        chgVal = "B";

    } else if ((prevval === "다") && (nextval === "라")) {
        chgVal = "C";

    } else if ((prevval === "라") && (nextval === "마")) {
        chgVal = "D";

    } else if ((prevval === "마") && (nextval === "바")) {
        chgVal = "E";

    } else if ((prevval === "바") && (nextval === "사")) {
        chgVal = "F";

    } else if ((prevval === "사") && (nextval === "아")) {
        chgVal = "G";

    } else if ((prevval === "아") && (nextval === "자")) {
        chgVal = "H";

    } else if ((prevval === "자") && (nextval === "카")) {
        chgVal = "I";

    } else if ((prevval === "카") && (nextval === "타")) {
        chgVal = "J";

    } else if ((prevval === "타") && (nextval === "파")) {
        chgVal = "K";

    } else if ((prevval === "파") && (nextval === "하")) {
        chgVal = "L";

    } else if ((prevval === "하") && (nextval === "힝")) {
        chgVal = "M";

    } else if ((prevval === "A") && (nextval === "Z")) {
        chgVal = "AZ";
    } else{
        chgVal = "ETC";

    }

    dma_select_list.set("listStatCd", combo_stat.getValue());
    dma_select_list.set("spotIsuTrdMktTpCd", combo_market.getValue());
    dma_select_list.set("searchComAbbrv", txb_jongmokName.getValue());
    dma_select_list.set("beginIndex", chgVal);
    dma_select_list.set("page",  1);
    dma_select_list.set("size",  10);

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
};

